module Aihc.Lir.Syntax (Module(..), Item(..), Symbol(..), Var(..), Label(..), Type(..), typeBits, isIntegerType, isFloatType, CallingConvention(..), Linkage(..), Signature(..), Function(..), functionSignature, ExternFunction(..), Global(..), Constant(..), ConstantExpr(..), ConstantOp(..), DataItem(..), DataField(..), Block(..), Instruction(..), Operation(..), BinaryOp(..), UnaryOp(..), WideOp(..), CompareOp(..), FloatBinaryOp(..), FloatUnaryOp(..), ConvertOp(..), Address(..), AddressConstant(..), byteAddress, addressByteOffset, Alignment(..), byteAlignment, wordAlignment, alignmentInBytes, Terminator(..), terminatorTargets, Target(..), SwitchCase(..), Operand(..), Literal(..), forOperationOperands, forTerminatorOperands) where {
import Data.ByteString (ByteString);
import Data.Foldable (traverse_);
import Data.Text (Text);
newtype Module = Module { moduleItems :: [Item] } deriving (Eq, Show);
data Item = ItemFunction !Function | ItemExternFunction !ExternFunction | ItemGlobal !Global | ItemData !DataItem | ItemExternData !Symbol | ItemConstant !Constant | ItemInclude !Text deriving (Eq, Show);
newtype Symbol = Symbol { unSymbol :: Text } deriving (Eq, Ord, Show);
newtype Var = Var { unVar :: Text } deriving (Eq, Ord, Show);
newtype Label = Label { unLabel :: Text } deriving (Eq, Ord, Show);
data Type = I1 | I8 | I16 | I32 | I64 | F32 | F64 | Ptr | Code deriving (Eq, Ord, Show, Enum, Bounded);
typeBits :: Type -> Int;
typeBits ty = case ty of {
  I1 -> 1;
  I8 -> 8;
  I16 -> 16;
  I32 -> 32;
  I64 -> 64;
  F32 -> 32;
  F64 -> 64;
  Ptr -> 64;
  Code -> 64};
isIntegerType :: Type -> Bool;
isIntegerType ty = ty `elem` [I8, I16, I32, I64];
isFloatType :: Type -> Bool;
isFloatType ty = ty `elem` [F32, F64];
data CallingConvention = AihcConvention | CConvention deriving (Eq, Ord, Show);
data Linkage = Internal | Export | Inline deriving (Eq, Ord, Show);
data Signature = Signature { signatureParameters :: ![Type], signatureResults :: ![Type], signatureConvention :: !CallingConvention } deriving (Eq, Ord, Show);
data Function = Function { functionName :: !Symbol, functionLinkage :: !Linkage, functionParameters :: ![(Var, Type)], functionResults :: ![Type], functionConvention :: !CallingConvention, functionBlocks :: ![Block] } deriving (Eq, Show);
functionSignature :: Function -> Signature;
functionSignature function = Signature {signatureParameters = map snd (functionParameters function), signatureResults = functionResults function, signatureConvention = functionConvention function};
data ExternFunction = ExternFunction { externFunctionName :: !Symbol, externFunctionSignature :: !Signature } deriving (Eq, Show);
data Global = Global { globalName :: !Symbol, globalType :: !Type } deriving (Eq, Show);
data Constant = Constant { constantName :: !Symbol, constantValue :: !ConstantExpr } deriving (Eq, Show);
data ConstantExpr = ConstantInt !Integer | ConstantRef !Symbol | ConstantWords !ConstantExpr | ConstantNegate !ConstantExpr | ConstantBinary !ConstantOp !ConstantExpr !ConstantExpr deriving (Eq, Show);
data ConstantOp = ConstantAdd | ConstantSub | ConstantMul | ConstantQuot | ConstantRem deriving (Eq, Show);
data DataItem = DataItem { dataName :: !Symbol, dataLinkage :: !Linkage, dataMutable :: !Bool, dataAlignment :: !Integer, dataFields :: ![DataField] } deriving (Eq, Show);
data DataField = DataInt !Type !Integer | DataIntConstant !Type !Symbol | DataFloat !Type !Double | DataSymbol !Symbol !Integer | DataNull | DataWord !Integer | DataWordConstant !Symbol | DataCode !(Maybe Symbol) | DataBytes !ByteString | DataZero !Integer deriving (Eq, Show);
data Block = Block { blockLabel :: !Label, blockParameters :: ![(Var, Type)], blockInstructions :: ![Instruction], blockTerminator :: !Terminator } deriving (Eq, Show);
data Instruction = Instruction { instructionResults :: ![Var], instructionOperation :: !Operation } deriving (Eq, Show);
data Operation = Binary !BinaryOp !Type !Operand !Operand | Unary !UnaryOp !Type !Operand | Wide !WideOp !Type !Operand !Operand | Compare !CompareOp !Type !Operand !Operand | FloatBinary !FloatBinaryOp !Type !Operand !Operand | FloatUnary !FloatUnaryOp !Type !Operand | Convert !ConvertOp !Type !Operand !Type | PtrToInt !Operand | PtrFromInt !Operand | Select !Type !Operand !Operand !Operand | Load !Type !Address !Alignment | Store !Type !Operand !Address !Alignment | PtrAdd !Operand !Operand | StackAlloc !Integer !Alignment | GlobalGet !Symbol | GlobalSet !Symbol !Operand | Call !Symbol ![Operand] | CallIndirect !Operand ![Operand] !Signature deriving (Eq, Show);
data BinaryOp = Add | Sub | Mul | DivS | DivU | RemS | RemU | And | Or | Xor | Shl | ShrS | ShrU deriving (Eq, Ord, Show, Enum, Bounded);
data UnaryOp = Clz | Ctz | Popcount deriving (Eq, Ord, Show, Enum, Bounded);
data WideOp = MulWideS | MulWideU | AddCarry | SubBorrow deriving (Eq, Ord, Show, Enum, Bounded);
data CompareOp = Eq | Ne | LtS | LtU | LeS | LeU | GtS | GtU | GeS | GeU | FLt | FLe | FGt | FGe deriving (Eq, Ord, Show, Enum, Bounded);
data FloatBinaryOp = FAdd | FSub | FMul | FDiv deriving (Eq, Ord, Show, Enum, Bounded);
data FloatUnaryOp = FNeg | FAbs | FSqrt deriving (Eq, Ord, Show, Enum, Bounded);
data ConvertOp = SExt | ZExt | Trunc | IToFS | IToFU | FToIS | FToIU | FpExt | FpTrunc | Bitcast deriving (Eq, Ord, Show, Enum, Bounded);
data Address = Address { addressBase :: !Operand, addressOffset :: !Integer, addressWordOffset :: !Integer, addressConstants :: ![AddressConstant] } deriving (Eq, Show);
data AddressConstant = AddressConstant { addressConstantName :: !Symbol, addressConstantNegative :: !Bool, addressConstantInWords :: !Bool } deriving (Eq, Show);
data Alignment = AlignBytes !Integer | AlignWords !Integer deriving (Eq, Show);
byteAlignment :: Integer -> Alignment;
byteAlignment = AlignBytes;
wordAlignment :: Integer -> Alignment;
wordAlignment = AlignWords;
alignmentInBytes :: Integer -> Alignment -> Integer;
alignmentInBytes wordBytes alignment = case alignment of {
  AlignBytes value -> value;
  AlignWords count -> count * wordBytes};
byteAddress :: Operand -> Integer -> Address;
byteAddress base offset = Address base offset 0 [];
addressByteOffset :: Integer -> Address -> Integer;
addressByteOffset wordBytes address | null (addressConstants address) = addressOffset address + addressWordOffset address * wordBytes | otherwise = error "Lir address constants reached a backend unresolved";
data Terminator = Jump !Target | Branch !Operand !Target !Target | Switch !Type !Operand ![SwitchCase] !(Maybe Target) | Return ![Operand] | TailCall !Symbol ![Operand] | TailCallIndirect !Operand ![Operand] !Signature | Trap !Text deriving (Eq, Show);
terminatorTargets :: Terminator -> [Target];
terminatorTargets terminator = case terminator of {
  Jump target -> [target];
  Branch _ whenTrue whenFalse -> [whenTrue, whenFalse];
  Switch _ _ cases fallback -> map switchCaseTarget cases <> maybe [] pure fallback;
  _ -> []};
data Target = Target { targetLabel :: !Label, targetArguments :: ![Operand] } deriving (Eq, Show);
data SwitchCase = SwitchCase { switchCaseValue :: !Integer, switchCaseTarget :: !Target } | SwitchCaseConstant { switchCaseConstant :: !Symbol, switchCaseTarget :: !Target } deriving (Eq, Show);
data Operand = OperandVar !Var | OperandLiteral !Literal deriving (Eq, Show);
data Literal = LitInt !Integer | LitFloat !Double | LitNull | LitSymbol !Symbol deriving (Eq, Show);
forOperationOperands :: (Applicative f) => (Operand -> f ()) -> Operation -> f ();
forOperationOperands act operation = case operation of {
  Binary _ _ left right -> act left *> act right;
  Unary _ _ value -> act value;
  Wide _ _ left right -> act left *> act right;
  Compare _ _ left right -> act left *> act right;
  FloatBinary _ _ left right -> act left *> act right;
  FloatUnary _ _ value -> act value;
  Convert _ _ value _ -> act value;
  PtrToInt value -> act value;
  PtrFromInt value -> act value;
  Select _ condition left right -> act condition *> act left *> act right;
  Load _ address _ -> act (addressBase address);
  Store _ value address _ -> act value *> act (addressBase address);
  PtrAdd base offset -> act base *> act offset;
  StackAlloc _ _ -> pure ();
  GlobalGet _ -> pure ();
  GlobalSet _ value -> act value;
  Call _ arguments -> traverse_ act arguments;
  CallIndirect callee arguments _ -> act callee *> traverse_ act arguments};
forTerminatorOperands :: (Applicative f) => (Operand -> f ()) -> Terminator -> f ();
forTerminatorOperands act terminator = case terminator of {
  Jump jump -> traverse_ act (targetArguments jump);
  Branch condition whenTrue whenFalse -> act condition *> traverse_ act (targetArguments whenTrue) *> traverse_ act (targetArguments whenFalse);
  Switch _ scrutinee cases fallback -> act scrutinee *> traverse_ (traverse_ act . targetArguments . switchCaseTarget) cases *> traverse_ (traverse_ act . targetArguments) fallback;
  Return values -> traverse_ act values;
  TailCall _ arguments -> traverse_ act arguments;
  TailCallIndirect callee arguments _ -> act callee *> traverse_ act arguments;
  Trap _ -> pure ()}
}
